    selectedCarTypeTagIds,
  } = useCarTypeTagIdsFilter()
  const onSelect = () => {
 (...)
  }
  return (
    <MultipleSelectionProvider
      value={selectedCarTypeTagIds}
      onSelect={onSelect}
    >
      {carTypeTags.map(({ id, name }) => (
         <Tag id={id} name={name} variant="rounded" />
      ))}
    </MultipleSelectionProvider>
  )
}
Tag는 UI 모양만을, 나머지 혜택 태그 관련 로직은 hook을 사용하여 관심사를 분리했습니다. 이 과정에서 컴포넌트 간 결합도를 낮추었기 때문에 Tag가 아닌 다른 컴포넌트와 조합하여 사용하거나 다른 hook을 만들어 사용하기에도 편리합니다.
또한 리팩토링 과정에서 혜택에 관련된 도메인 로직을 분리할 때 features라는 폴더를 만들어 도메인 별 로직을 한 곳에서 관리할 수 있도록 했습니다. carTypeTagIds 폴더에 관련 파일을 모아서 관리했는데, 이처럼 도메인에 따라 폴더를 나누는 패턴을 feature-driven component 패턴이라고 합니다.
앞선 예시는 간단한 사례라 숙련된 개발자라면 첫 단계부터 제대로 추상화를 했을 것입니다. 그러나 컴포넌트나 화면 구성이 복잡할수록, 기획과 디자인의 변경이 잦을수록, 미리 모든 걸 예상해서 로직을 분리하는 일은 어렵습니다. 이럴 때는 충분한 시간이 지나고 코드가 안정화됐을 때 추상화해 폴더 및 파일을 분리하는 방식을 사용하는 게 도움될 수 있습니다.
Storybook 활용
프론트엔드 개발자들 간의 협업에서는 종종 같은 컴포넌트를 중복해서 만드는 경우가 있습니다. 컴포넌트의 존재를 모르고 새로 만드는 경우도 있고, 알고는 있지만 컴포넌트 사용법을 몰라서 사용하지 않는 경우도 종종 있습니다. 서버 개발자와 프론트엔드 개발자 간에 API 명세서가 필요한 것처럼, 프론트엔드 개발자들 간에도 컴포넌트 사용법에 대한 명세가

소개
안녕하세요. 쏘카 자산개발(Asset)팀 백엔드 개발자 원스톤입니다. 저는 쏘카 존과 차량 도메인을 개발하고 있습니다.
지속 성장하는 소프트웨어를 만들기 위한 코드의 품질 개선 노력들을 글로 풀어내려고 합니다. 먼저 차량재배치의 레거시 개선 작업이 필요했던 이유와 차량재배치 비즈니스의 도메인 지식과 코드 리팩터링을 순서대로 소개하겠습니다.
개선 목적
차량재배치는 오래전 개발되어 방치되어 있었고 크게 두 가지 문제가 있었습니다.
- 
코드 레벨에서의 문제로 일부 기능 수정 또는 오류 발생 시 수정해야 하는 부분이 명확하지 않았습니다. 하나의 거대 클래스로 이루어진 모든 코드를 파악한 뒤 일부분을 수정하는 방식으로 유지보수하고 있어 사이드이펙트에 대한 두려움이 존재했습니다. 
- 
기술 레벨에서의 문제로 기술조직 대부분이 사용 중인 AWS DMS와 카프카를 이용하지 않고 맥스웰과 키네시스를 이용하고 있었습니다. 맥스웰을 사용할 줄 아는 개발자는 극히 드물었고 사용하는 곳도 몇 군데 없었습니다. 문제가 발생했을 때 참고 문헌이 없어 해결하기가 쉽지 않았습니다. 맥스웰 기능에 문제가 생기면 수동으로 작업을 처리해야 했습니다. 해당 문제는 자주 발생했습니다. 결국, PM, 개발자, 사업부 모두의 동의를 얻어 일감으로 처리하게 됐습니다. 
차량재배치 설명
쏘카는 존이라는 차량이 존재하는 공간을 갖고 있습니다. 매출 지표를 참고하거나 침수 등의 사유가 발생하면 한 존에서 다른 존으로 차량 이동을 수행합니다. 그것을 차량재배치로 정의합니다. 내부 시스템인 존관리시스템에서 차량재배치를 요청하고 실제 운전자가 차량을 이동시키면 이벤트를 받아 차량재배치를 수행합니다.
스프링 카프카로 변경된 아키텍처 및 코드 설명
기존 코드 설명
기존 코드는 다음과 같이 하나의 클래스에 모든 로직이 있었습니다. 키네시스와 스프링 로직이 비즈니스 로직에 들어가 있어서 분석하기 힘들었고, 키네시스를 다른 기술로 바꾸면 모든 코드를 고쳐야했습니다. 게다가 테스트코드도 없었습니다.
